examples.code:
terraform {
  required_version = ">= 1.10"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0"
    }
  }
}

provider "aws" {
  alias  = "sa"
  region = "sa-east-1"
}
module "replica" {
  source    = "./modules/bucket"
  providers = { aws = aws.sa }
  name      = "nicocano-replica"
}

locals {
  tamanos = { default = "t3.micro", staging = "t3.small", prod = "m7i.large" }
  instance_type = lookup(local.tamanos, terraform.workspace, "t3.micro")
}
resource "aws_instance" "app" {
  ami           = data.aws_ami.ubuntu.id
  instance_type = local.instance_type
  tags          = { Name = "app-${terraform.workspace}" }
}

data "terraform_remote_state" "network" {
  backend = "s3"
  config = {
    bucket = "nicocano-tfstate"
    key    = "network/prod/terraform.tfstate"
    region = "us-east-1"
  }
}
resource "aws_instance" "app" {
  subnet_id = data.terraform_remote_state.network.outputs.private_subnet_ids[0]
}
